# region: gather
def gather(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: render
def render(xs, limit=5):
    return [v if v <= limit else limit for v in xs[1:]]

# region: intake
def intake(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: sift
def sift(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return sift(intake(render(gather(raw))))

